const payload = $json.body ?? $json;
const volumeTier = `${payload.monthlyPieceVolume ?? ''}`.toLowerCase();
const phiSignal = `${payload.phiStatus ?? ''}`.toLowerCase();
const priorityScore = (volumeTier.includes('25k') ? 3 : volumeTier.includes('10k') ? 2 : volumeTier.includes('2k') ? 1 : 0) + (phiSignal.includes('mostly') ? 1 : 0);
const leadId = `DEMO-PRESORT-${Date.now()}`;
const smsWarmUp = `Hi ${(payload.contactName ?? 'there').split(' ')[0]}, this is ${payload.companyName ?? 'the team'}'s automated assistant. We received your inquiry and are calling in about 30 seconds. — Lone Star Mail Services`;
return [{ json: { leadId, priority: priorityScore >= 2 ? 'high' : priorityScore >= 1 ? 'medium' : 'standard', smsWarmUp, callbackDelaySeconds: 30, vapiAgent: 'inbound-callback', nextAction: 'Send SMS warm-up, schedule Vapi callback in 30 seconds.', lead: payload } }];
